-- Bảng mua hàng cho app v2. Chỉ TẠO MỚI, không đụng bảng nào đang có.
create table if not exists public.v2_dim_po (
  lo_id bigint not null references public.v2_nap_lo(id) on delete cascade,
  stt   int    not null,          -- thứ tự dòng trong file, giữ khoá duy nhất
  po                text,
  sku               text,
  mo_ta             text,
  supplier_code     text,
  supplier_name     text,
  don_vi            text,
  sl_dat            int,
  sl_xac_nhan       int,
  gia_mua           numeric,
  thanh_tien        numeric,
  thanh_tien_vat    numeric,
  ngay_dat          date,
  ngay_ncc_xac_nhan date,
  ngay_nhan         date,
  leadtime_nguon    int,
  thang             int,
  nam               int,
  trang_thai_nhan   text,
  ghi_chu           text,
  ngay_hoa_don      date,
  han_tt_ngay       int,
  ngay_den_han      date,
  trang_thai_tt     text,
  so_ngay_qua_han   int,
  da_tra            numeric,
  ngay_tra          date,
  con_no            numeric,
  primary key (lo_id, stt)
);
create index if not exists v2_dim_po_sku_idx on public.v2_dim_po (lo_id, sku);
create index if not exists v2_dim_po_ncc_idx on public.v2_dim_po (lo_id, supplier_name);
alter table public.v2_dim_po enable row level security;
drop policy if exists v2_dim_po_doc on public.v2_dim_po;
create policy v2_dim_po_doc on public.v2_dim_po for select to anon, authenticated using (true);

create or replace view public.v2_po_hien_hanh as
  select p.* from public.v2_dim_po p
  join public.v2_nap_lo l on l.id = p.lo_id and l.dang_dung;

delete from public.v2_dim_po where lo_id in (select id from public.v2_nap_lo where dang_dung);

insert into public.v2_dim_po (lo_id, stt, po, sku, mo_ta, supplier_code, supplier_name, don_vi, sl_dat, sl_xac_nhan, gia_mua, thanh_tien, thanh_tien_vat, ngay_dat, ngay_ncc_xac_nhan, ngay_nhan, leadtime_nguon, thang, nam, trang_thai_nhan, ghi_chu, ngay_hoa_don, han_tt_ngay, ngay_den_han, trang_thai_tt, so_ngay_qua_han, da_tra, ngay_tra, con_no)
